              choiceValues: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934538",
              value: ri!typeFilter,
              saveInto: {
                ri!typeFilter,
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
