              choiceValues: #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3640108",
              value: ri!statusFilter,
              saveInto: {
                ri!statusFilter,
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
                    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                  )
                )
              }
            )
          }
